package dev.kasoti.eval.fixtures

import dev.kasoti.qr.KeyRing
import dev.kasoti.qr.QrPayload
import java.security.KeyPair
import java.security.KeyPairGenerator

/**
 * The D-QR fixture corpus (EVAL.md §2, DATA.md §7).
 *
 * The payload bytes are generated, not collected, so the set contains zero PII and can be
 * regenerated byte-for-byte from a seed. The *signatures* are produced at run time by the
 * harness stub, because a per-JVM keypair means a signature on disk would be unverifiable
 * on the next run.
 *
 * The corpus is built so that every arm of [dev.kasoti.qr.SecureQr] is exercised:
 * valid-signed, tampered-payload, tampered-signature, post-signing field substitution,
 * wrong-key, stale-keys and unsigned. A QR suite that only tested the valid case would be a
 * tautology, and one that only tested rejection could be satisfied by refusing everything.
 */
object QrFixtures {

    /** EVAL.md §2 target for D-QR. Below this the tamper rate has a wide confidence band. */
    const val TARGET_SIZE = 300

    const val PAYLOAD_VERSION = 1

    /** The deterministic clock every fixture date is derived from. Never `now()`. */
    const val FIXED_NOW = "2026-09-01T00:00:00Z"

    /** Ring rotation date. Deliberately inside the lifetime of one key and outside another's. */
    const val ROTATED_AFTER = "2026-06-01"

    /**
     * Bundled test issuers. Each gets its *own* keypair, because
     * [dev.kasoti.qr.SecureQr.verify] takes the first key in the ring that verifies — if
     * they all shared one public key, key selection would not be under test at all and a
     * stale key would report as valid.
     */
    val ISSUER_KEY_IDS = listOf("uidai_test", "issuer_b_test", "issuer_c_test")

    /** The key whose expiry is *after* [ROTATED_AFTER], so its signatures are `Valid`. */
    const val FRESH_KEY_ID = "uidai_test"

    data class Case(
        val id: String,
        val payload: QrPayload,
        val keyId: String,
        /** What the suite asserts [dev.kasoti.qr.SecureQr.verify] returns. */
        val expectation: Expectation,
        val mutation: String,
    )

    /**
     * What the suite asserts `dev.kasoti.qr.SecureQr.verify` returns.
     *
     * [REJECTED] is deliberately "any non-accepting outcome" rather than
     * `SigResult.Invalid`. `SecureQr` returns `Invalid` only for an *unsigned* payload; a
     * signed payload whose signature does not check out fails against every key in the ring,
     * so `SecureQr` reaches its no-key-matched branch and reports `UnknownKey`. That label
     * reads oddly — the key did match the payload's declared issuer, it just did not verify —
     * but it is the product's contract, and `dev.kasoti.fusion.RedRules.qrSignature` collapses
     * every rejecting outcome into `R-QR-01` behind a single `signatureValid` boolean, so the
     * distinction has no consequence for the verdict. Asserting `Invalid` here would be
     * asserting a label, not the security property.
     */
    enum class Expectation {
        /** A genuine, correctly signed payload from a fresh bundled key. */
        VALID,

        /** Must not be accepted: tampered bytes, a re-encoded field, or an unbundled key. */
        REJECTED,

        /** Correctly signed, but the ring's rotation date has passed the key's expiry. */
        STALE,

        /** No signature at all: the legacy path, which is specifically `Invalid`. */
        UNSIGNED,
    }

    data class Corpus(
        val cases: List<Case>,
        val ring: KeyRing,
        val issuerKeys: Map<String, KeyPair>,
        val unbundledKeyIds: List<String>,
    )

    /**
     * @param seed fixture seed. The corpus is a pure function of it, so two runs with the
     *   same seed exercise the same payload bytes.
     */
    fun build(seed: Long, size: Int = TARGET_SIZE): Corpus {
        val issuerKeys = ISSUER_KEY_IDS.associateWith { newKeyPair() }
        val unbundledKeyId = "uidai_test_rogue"
        val unbundled = newKeyPair()

        val ring = KeyRing(
            keys = ISSUER_KEY_IDS.associateWith { keyId ->
                KeyRing.KeyEntry(
                    keyId = keyId,
                    x509PublicKey = issuerKeys.getValue(keyId).public.encoded,
                    issuedAt = "2026-01-01",
                    // Only the first key survives the rotation date, so `Valid` and `Stale`
                    // are distinct outcomes reached by distinct keys.
                    expiresAt = if (keyId == FRESH_KEY_ID) "2030-01-01" else "2020-01-01",
                    provenance = KeyProvenance.TEST_HARNESS.wireValue,
                )
            },
            rotatedAfter = ROTATED_AFTER,
        )

        val cases = ArrayList<Case>(size + size / 10)
        val fresh = issuerKeys.getValue(FRESH_KEY_ID)
        for (index in 0 until size) {
            val id = "qr-%05d".format(index)
            // Every tamper arm is signed by the FRESH key on purpose. A tampered payload
            // signed by an expired key verifies-and-is-stale, and `SecureQr` correctly answers
            // StaleKeys rather than Invalid — which would test the rotation check, not the
            // tamper check. The stale-key behaviour has its own arm below.
            val keyId = FRESH_KEY_ID
            val keyPair = fresh
            val fields = fieldsFor(seed, index)
            val raw = encodePayload(fields)
            val arm = index % 3

            cases += when (arm) {
                0 -> Case(
                    id, signed(raw, fields, keyPair), keyId, Expectation.VALID, "none",
                )

                1 -> {
                    // Flip one bit of the payload after signing: the signature no longer
                    // covers the bytes.
                    val tampered = raw.copyOf()
                    val at = index % tampered.size
                    tampered[at] = (tampered[at].toInt() xor 0x01).toByte()
                    val signature = HarnessSigner.sign(keyPair.private, raw)
                    Case(
                        id, payload(tampered, fields, signature, signed = true), keyId,
                        Expectation.REJECTED, "payload-bit-flip@$at",
                    )
                }

                else -> {
                    // Sign the original, then rewrite the payload: the realistic forgery,
                    // where an attacker re-encodes a visible field and keeps the old
                    // signature. The rewrite has to land in `raw`, because `raw` is what the
                    // signature covers — editing only the decoded field map would leave the
                    // signed bytes intact and the signature would *correctly* still verify.
                    val signature = HarnessSigner.sign(keyPair.private, raw)
                    val forged = fields.toMutableMap().apply { put("name", forgedName(index)) }
                    Case(
                        id, payload(encodePayload(forged), forged, signature, signed = true), keyId,
                        Expectation.REJECTED, "field-substitution-after-signing",
                    )
                }
            }
        }

        // Keys outside the rotation window, on their own so the count is not entangled with
        // the tampering arms.
        val staleKeyIds = ISSUER_KEY_IDS.filter { it != FRESH_KEY_ID }
        for ((index, keyId) in staleKeyIds.withIndex()) {
            val fields = fieldsFor(seed, 800_000 + index)
            val raw = encodePayload(fields)
            cases += Case(
                "qr-stale-%03d".format(index),
                signed(raw, fields, issuerKeys.getValue(keyId)),
                keyId,
                Expectation.STALE,
                "expired-key",
            )
        }

        // Signed by a key nobody bundled: a real signature we cannot attribute.
        for (index in 0 until maxOf(1, size / 20)) {
            val fields = fieldsFor(seed, 700_000 + index)
            val raw = encodePayload(fields)
            cases += Case(
                "qr-rogue-%03d".format(index),
                signed(raw, fields, unbundled),
                unbundledKeyId,
                Expectation.REJECTED,
                "rogue-key",
            )
        }

        // Unsigned legacy payloads, so the suite can never pass without having checked that
        // an unsigned QR is not evidence.
        for (index in 0 until maxOf(1, size / 10)) {
            val fields = fieldsFor(seed, 900_000 + index)
            cases += Case(
                "qr-unsigned-%03d".format(index),
                payload(encodePayload(fields), fields, signature = null, signed = false),
                FRESH_KEY_ID,
                Expectation.UNSIGNED,
                "no-signature",
            )
        }

        return Corpus(cases, ring, issuerKeys, listOf(unbundledKeyId))
    }

    /** The verifier the corpus was signed against. The fixtures and the suite share it. */
    fun verifier(): dev.kasoti.crypto.SignatureVerifier =
        HarnessStubSignatureVerifier.instance().second

    private fun newKeyPair(): KeyPair =
        KeyPairGenerator.getInstance("RSA").apply { initialize(2048) }.generateKeyPair()

    private fun signed(raw: ByteArray, fields: Map<String, String>, keyPair: KeyPair): QrPayload =
        payload(raw, fields, HarnessSigner.sign(keyPair.private, raw), signed = true)

    private fun fieldsFor(seed: Long, index: Int): Map<String, String> {
        val hex = HarnessSigner.stableId("qr/$seed", index).joinToString("") { "%02x".format(it) }
        val given = SURNAMES[index % SURNAMES.size]
        val family = GIVEN_NAMES[(index / SURNAMES.size) % GIVEN_NAMES.size]
        return linkedMapOf(
            "ra" to "kasoti-test-$seed-$index",
            "ver" to PAYLOAD_VERSION.toString(),
            "name" to "$given $family",
            "dob" to "%04d-%02d-%02d".format(1970 + index % 40, 1 + index % 12, 1 + index % 28),
            "gender" to if (index % 2 == 0) "M" else "F",
            "dist" to "D%02d".format(index % 40),
            "st" to "S%02d".format(index % 12),
            // A non-PII token, so a payload byte is a byte we can flip deterministically.
            "tc" to hex.take(16),
        )
    }

    private fun forgedName(index: Int): String = "FORGED $index ${GIVEN_NAMES[index % GIVEN_NAMES.size]}"

    /**
     * Wire format: `key=value` pairs joined by `&`, the legacy shape
     * [dev.kasoti.qr.UnsignedQr.parse] already understands. Chosen so the signed and
     * unsigned paths parse the same bytes.
     */
    private fun encodePayload(fields: Map<String, String>): ByteArray =
        fields.entries.joinToString("&") { (k, v) -> "$k=$v" }.toByteArray(Charsets.UTF_8)

    private fun payload(
        raw: ByteArray,
        fields: Map<String, String>,
        signature: ByteArray?,
        signed: Boolean,
    ): QrPayload = QrPayload(
        raw = raw,
        version = PAYLOAD_VERSION,
        fields = fields,
        signature = signature,
        signed = signed,
    )

    private val SURNAMES = listOf("SHARMA", "VERMA", "PATEL", "SINGH", "GUPTA", "REDDY", "NAIR", "BOSE")
    private val GIVEN_NAMES = listOf("RAMESH", "SURESH", "ANITA", "VIKRAM", "MEENA", "ARJUN", "KAVITA", "DEV")
}
